import{z as t,x as o,o as e,c as i,q as A,j as s,D as E,d as l,s as B,S as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"评测：任务成功率与过程","description":"","frontmatter":{"title":"评测：任务成功率与过程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-eval-success-process.md","filePath":"llm/agent-eval-success-process.md","lastUpdated":1791063341000}'),h={name:"llm/agent-eval-success-process.md"};function p(m,a,c,C,d,D){const r=o("Mermaid");return e(),i("div",null,[a[2]||(a[2]=A('<h1 id="评测-任务成功率与过程" tabindex="-1">评测：任务成功率与过程 <a class="header-anchor" href="#评测-任务成功率与过程" aria-label="Permalink to &quot;评测：任务成功率与过程&quot;">​</a></h1><div class="epigraph"><p>只报一个成功率，等于把解码随机、环境漂移、重试策略三种噪声蒸进一个数；结果说明「成了没」，过程说明「为什么」。</p><footer>—— 据 Jimenez 等，SWE-bench，ICLR 2024；Zhou 等，WebArena，ICLR 2024 的评测合同整理</footer></div><p><a href="/llm/agent-error-recovery">上一课</a>给每级失败配了恢复动作；评测决定这些动作如何计入分数——不定义计分，恢复就是自说自话。主干已有<a href="/llm/agent-eval-protocol">智能体与工具评测协议</a>钉环境与预算、<a href="/llm/eval-variance-seed">评测方差与随机种子</a>钉噪声源；本课写指标本体：结果指标怎么选、过程指标怎么用、两者如何互相约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次任务成功率（SR）是被三重噪声污染的点估计：解码随机、环境非确定、重试与恢复策略本身影响成败。更隐蔽的是结果与过程的张力。只看结果，代理会学会取巧：删掉失败的测试让套件变绿、把答案硬编码进输出——结果函数写死就有人对它优化，这与 RL 里 reward hacking 同机制（<a href="/llm/process-supervision">过程监督 / PRM</a> 讲过结果监督的漏洞）。<span class="marginnote">术语翻译：reward hacking（奖励作弊）就是「找到评分规则的漏洞拿分，而不是真把事做成」。就像学生发现阅卷只看答案对不对，就把标准答案抄在橡皮上——分数有了，能力没有。</span>只看过程，就掉进好学生陷阱：步数少、格式规范、工具调用量适中，但任务没完成——过程指标是诊断维，不是目标函数。<span class="marginnote">直觉类比：好学生陷阱就是「笔记工整、坐姿端正、从不迟到，但卷子没写完」。这些行为都好量化，所以容易被当成 KPI；量化方便和真正重要是两回事。</span>第三个问题是没有协议的数字不可比：环境重没重置、允许几次尝试、失败算不算预算耗尽（<a href="/llm/agent-loop-design-space">Agent 循环的设计空间</a>的三分结束语义），每一条都会改变分数的含义。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>结果侧</strong>三件：SR 作为基线；<a href="/llm/pass-at-k">pass@k</a> 把「k 次尝试预算内能过」变成显式合同，对应给代理多几次机会的产品现实；\\(\\mathrm{pass}^k\\)——k 次独立运行全部通过——把稳定性变成指标，<a href="/llm/taubench-agentbench">τ-bench / AgentBench</a> 用它惩罚「偶尔蒙对」。部分学分用分档 rubric，但评分器若是模型要校准偏差。<strong>过程侧</strong>不进目标函数、只进归因：步数、工具调用数、token 成本、政策违规次数（τ-bench 的合规检查）、人工介入次数、各级失败的占比。<span class="marginnote">为什么重要：过程指标一旦被当成优化目标（比如「把平均步数降下来」考核模型），模型就会学出为省步数而跳过验证的行为——步数降了，成功率跟着塌。所以过程数字只用来回答「失败发生在哪」，不用来打分。</span><strong>协议</strong>继承评测协议课：环境版本钉住（镜像、commit、快照）、重置规则、网络策略、尝试次数写进报告。<strong>基准地图</strong>按域选：<a href="/llm/swebench-verified">SWE-bench Verified</a>（真实仓库加测试）、<a href="/llm/osworld">OSWorld</a>（虚拟机 GUI）、<a href="/llm/webarena">WebArena / VisualWebArena</a>（自托管网站）、<a href="/llm/terminal-bench-2">Terminal-Bench 2</a>（终端任务）、<a href="/llm/bfcl">BFCL 工具调用评测</a>（单步调用下限）。</p>',7)),(e(),s(n,null,{default:E(()=>[B(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22k%20%E6%AC%A1%E7%8B%AC%E7%AB%8B%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20SR%5B%22%E7%BB%93%E6%9E%9C%EF%BC%9ASR%20%2F%20pass%40k%20%2F%20pass%5Ek%22%5D%0A%20%20RUN%20--%3E%20PROC%5B%22%E8%BF%87%E7%A8%8B%EF%BC%9A%E6%AD%A5%E6%95%B0%E3%80%81%E6%88%90%E6%9C%AC%E3%80%81%E8%BF%9D%E8%A7%84%E3%80%81%E6%8E%A5%E7%AE%A1%22%5D%0A%20%20SR%20--%3E%20ATTR%7B%22%E5%A4%B1%E8%B4%A5%E5%BD%92%E5%9B%A0%22%7D%0A%20%20PROC%20--%3E%20ATTR%0A%20%20ATTR%20--%3E%7C%22%E6%AD%BB%E5%9C%A8%E9%A2%84%E7%AE%97%22%7C%20BUDGET%5B%22%E6%94%B9%E9%A2%84%E7%AE%97%E8%AF%AD%E4%B9%89%E6%88%96%E7%A0%8D%E6%AD%A5%E6%95%B0%22%5D%0A%20%20ATTR%20--%3E%7C%22%E6%AD%BB%E5%9C%A8%E9%AA%8C%E8%AF%81%22%7C%20VERIFY%5B%22%E6%94%B9%E9%AA%8C%E8%AF%81%E5%99%A8%E6%88%96%E6%81%A2%E5%A4%8D%E7%AD%96%E7%95%A5%22%5D%0A%20%20ATTR%20--%3E%7C%22%E6%AD%BB%E5%9C%A8%E5%B7%A5%E5%85%B7%22%7C%20TOOL%5B%22%E6%94%B9%20schema%20%E6%88%96%E6%8D%A2%E5%B7%A5%E5%85%B7%22%5D%0A%20%20ATTR%20--%3E%7C%22%E8%BF%9D%E8%A7%84%E4%BD%86%E7%BB%93%E6%9E%9C%E5%AF%B9%22%7C%20HACK%5B%22%E6%94%B6%E7%B4%A7%E7%BB%93%E6%9E%9C%E5%87%BD%E6%95%B0%EF%BC%9A%E9%98%B2%20hacking%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\mathrm{pass}^k\\) 与 pass@k 的差就是稳定性：前者要求 k 次全对，暴露的是恢复与一致性（回指<a href="/llm/agent-error-recovery">错误恢复与重试</a>——恢复好的代理才可能次次过）；后者只要求一次，奖励的是尝试次数。过程指标的第一用途不是优化而是分桶归因：把失败按「预算耗尽、验证否决、工具失败、策略失败」分桶（桶沿就是三分结束语义），每个桶对应不同的修法——预算桶去砍步数，验证桶去修恢复，工具桶去改 schema。能力上限的另一把尺是时间：<a href="/llm/metr-time-horizon">METR Time Horizon</a> 把成功率换算成「能稳定做多长的任务」，适合跨代比较，不适合单次发布决策。</p><p><span class="marginnote">\\(\\mathrm{pass}^k\\) 的数字直觉：若单次成功率 \\(p=0.8\\)，pass@5 约 \\(0.67\\) 的互补面几乎看不见，而 \\(\\mathrm{pass}^5 = 0.8^5 \\approx 0.33\\)——两个指标差出一倍多。产品若要求「每次都对」，评测必须用后者。</span></p>',3)),(e(),s(n,null,{default:E(()=>[B(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8D%95%E6%AC%A1%E6%88%90%E5%8A%9F%E7%8E%87%20p%22%5D%20--%3E%20A%5B%22pass%40k%EF%BC%9Ak%20%E6%AC%A1%E9%87%8C%E8%87%B3%E5%B0%91%E4%B8%80%E6%AC%A1%E8%BF%87%22%5D%0A%20%20P%20--%3E%20B%5B%22pass%5Ek%EF%BC%9Ak%20%E6%AC%A1%E7%8B%AC%E7%AB%8B%E8%BF%90%E8%A1%8C%E5%85%A8%E9%83%A8%E8%BF%87%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E5%A5%96%E5%8A%B1%E5%B0%9D%E8%AF%95%E6%AC%A1%E6%95%B0%EF%BC%9A%E8%BF%90%E6%B0%94%E5%A5%BD%E5%B0%B1%E8%83%BD%E4%B8%8A%E6%A6%9C%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E5%A5%96%E5%8A%B1%E7%A8%B3%E5%AE%9A%E6%80%A7%EF%BC%9A%E6%81%A2%E5%A4%8D%E4%B8%8E%E4%B8%80%E8%87%B4%E6%80%A7%E5%B7%AE%E7%9A%84%E4%BB%A3%E7%90%86%E7%8E%B0%E5%BD%A2%22%5D%0A%20%20A2%20--%3E%20A3%5B%22p%3D0.5%20%E6%97%B6%20pass%405%20%E7%BA%A6%2097%25%22%5D%0A%20%20B2%20--%3E%20B3%5B%22p%3D0.5%20%E6%97%B6%20pass%5E5%20%E7%BA%A6%203%25%22%5D%0A%20%20A3%20--%3E%20Q%7B%22%E4%BA%A7%E5%93%81%E8%AF%AD%E4%B9%89%E6%98%AF%E5%93%AA%E7%A7%8D%3F%EF%BC%9Cbr%2F%EF%BC%9E%E5%A4%9A%E8%AF%95%E5%87%A0%E6%AC%A1%E8%83%BD%E6%8E%A5%E5%8F%97%EF%BC%8C%E8%BF%98%E6%98%AF%E6%AF%8F%E6%AC%A1%E9%83%BD%E8%A6%81%E5%AF%B9%22%7D%0A%20%20B3%20--%3E%20Q%0A%20%20Q%20--%3E%7C%22%E8%83%BD%E5%A4%9A%E8%AF%95%22%7C%20PICKA%5B%22%E9%80%89%20pass%40k%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BF%85%E9%A1%BB%E6%AC%A1%E6%AC%A1%E5%AF%B9%22%7C%20PICKB%5B%22%E9%80%89%20pass%5Ek%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基准成功率不等于生产成功率：基准环境钉得住，生产环境会漂——线上表现要靠轨迹账本另算（<a href="/llm/agent-observability">可观测性</a>）。评测在环的训练用法（拿过程指标当奖励）是 RL 训练系统的事，本课只警告一句：过程指标进奖励，就会被优化。LLM 裁判做在线评分时，位置、长度与自我偏好要先校准（<a href="/llm/llm-judge-bias">LLM 裁判偏差</a>）。基准会饱和、会被污染，发布决策要配上自有任务集的回归（<a href="/llm/agent-regression-rollback">回归测试与版本回滚</a>）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结果指标三件：SR、pass@k（预算内能过）、pass^k（次次都对）；产品语义决定用哪个。</li><li>过程指标只做归因，不进目标函数；结果函数不可写死，防 hacking。</li><li>失败按结束语义分桶，每桶对应不同的修法。</li><li>协议先于数字：环境版本、重置、尝试次数写进报告，分数才可比。</li><li>基准选域：编码看 SWE-bench，GUI 看 OSWorld，稳定性看 τ-bench。</li><li>出处：据 SWE-bench（ICLR 2024）、WebArena（ICLR 2024）、τ-bench 等的评测合同与 METR 2025 报告整理。</li></ul>',4))])}const T=t(h,[["render",p]]);export{F as __pageData,T as default};
